target.css:
:root {
  --ink: #263640;
  --muted: #71818a;
  --paper: #fffdf7;
  --line: #dce5df;
  --clay: #c9664f;
  --clay-soft: #f8e3d9;
  --sage: #2f796c;
  --sage-soft: #dcefe9;
}

* {
  box-sizing: border-box;
}

.kiln-card {
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 15px 18px 13px;
  border-bottom: 1px solid var(--line);
}

.title-group p,
.firing-window p {
  margin: 0;
}

.eyebrow {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

h1 {
  margin: 3px 0 0;
  font-size: 21px;
  line-height: 1;
  letter-spacing: -0.4px;
}

.status {
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--sage-soft);
  color: var(--sage);
  font-size: 11px;
  font-weight: 800;
}

.booking {
  display: grid;
  grid-template-columns: 76px 1fr;
  gap: 13px;
  margin: 14px 18px;
  padding: 11px;
  border-radius: 12px;
  background: var(--clay-soft);
}

.date-block {
  display: flex;
  align-items: center;
  gap: 7px;
  padding-right: 12px;
  border-right: 1px solid var(--clay);
}

.date-block strong {
  color: var(--clay);
  font-size: 31px;
  line-height: 1;
  letter-spacing: -1.5px;
}

.date-block span {
  color: var(--clay);
  font-size: 10px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: 0.7px;
}

.firing-window {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.firing-window p {
  color: var(--clay);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.9px;
}

.firing-window strong {
  margin-top: 2px;
  font-size: 15px;
  line-height: 1.2;
}

.firing-window span {
  margin-top: 2px;
  color: var(--muted);
  font-size: 12px;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 0;
  padding: 0 18px 15px;
  list-style: none;
}

.details li {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 10px;
}

.detail-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.7px;
}

.details strong {
  overflow: hidden;
  font-size: 12px;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--clay);
}

button {
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--sage);
  font-size: 12px;
  font-weight: 800;
}

button span {
  margin-left: 3px;
  font-size: 15px;
}

